// Config plugin for the bundle server: lets the WebView load the bundled PWA
// from http://localhost:<port> and nothing else over cleartext.
const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod, withInfoPlist } = require('expo/config-plugins');

const RELEASE_CONFIG = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by modules/bundle-server/app.plugin.js. Cleartext only to the
     in-app loopback server that serves the bundled PWA. -->
<network-security-config>
  <base-config cleartextTrafficPermitted="false" />
  <domain-config cleartextTrafficPermitted="true">
    <domain includeSubdomains="false">localhost</domain>
    <domain includeSubdomains="false">127.0.0.1</domain>
  </domain-config>
</network-security-config>
`;

// Debug builds talk to Metro on the LAN over cleartext; this overlay replaces
// the release config for the debug variants only.
const DEBUG_CONFIG = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by modules/bundle-server/app.plugin.js (debug variant). -->
<network-security-config>
  <base-config cleartextTrafficPermitted="true" />
</network-security-config>
`;

function withLoopbackCleartextAndroid(config) {
  config = withAndroidManifest(config, (cfg) => {
    const app = cfg.modResults.manifest.application?.[0];
    if (!app) throw new Error('bundle-server: AndroidManifest has no <application>');
    app.$['android:networkSecurityConfig'] = '@xml/network_security_config';
    return cfg;
  });
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const appDir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src');
      for (const [variant, xml] of [
        ['main', RELEASE_CONFIG],
        ['debug', DEBUG_CONFIG],
        ['debugOptimized', DEBUG_CONFIG],
      ]) {
        const dir = path.join(appDir, variant, 'res', 'xml');
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(path.join(dir, 'network_security_config.xml'), xml);
      }
      return cfg;
    },
  ]);
}

function withLoopbackAts(config) {
  return withInfoPlist(config, (cfg) => {
    const ats = cfg.modResults.NSAppTransportSecurity ?? {};
    // ATS exception for local hosts only (localhost, loopback, .local).
    ats.NSAllowsLocalNetworking = true;
    cfg.modResults.NSAppTransportSecurity = ats;
    return cfg;
  });
}

module.exports = function withBundleServer(config) {
  return withLoopbackAts(withLoopbackCleartextAndroid(config));
};
